app.get('/api/ruc/:numero', async function(req, res){
  var num = (req.params.numero || '').replace(/[^0-9]/g,'');
  if(num.length !== 11 && num.length !== 8)
    return res.status(400).json({error:'RUC: 11 digitos. DNI: 8 digitos.'});
  var isDNI = num.length === 8;
  var DECOLECTA_TOKEN = 'sk_16024.nKMK3s3YuoWiXGzkVgWdHZem4qgpsP2X';

  /* METHOD 1: Decolecta API (token propio) */
  try{
    var url = isDNI
      ? 'https://api.decolecta.com/v1/reniec/dni?numero=' + num
      : 'https://api.decolecta.com/v1/sunat/ruc?numero=' + num;
    var r = await fetch(url, {
      headers:{
        'Content-Type':'application/json',
        'Authorization':'Bearer ' + DECOLECTA_TOKEN,
        'Referer':'https://skyblue-cotizaciones-production.up.railway.app'
      },
      signal: AbortSignal.timeout(8000)
    });
    if(r.ok){
      var d = await r.json();
      var nombre = d.razon_social || d.nombre_completo || (d.nombres ? (d.nombres+' '+(d.apellido_paterno||'')+' '+(d.apellido_materno||'')).trim() : '') || d.nombre || '';
      if(nombre){
        var dir = d.direccion || '';
        return res.json({
          tipo: isDNI ? 'DNI' : 'RUC',
          numero: num,
          nombre: nombre.trim(),
          direccion: dir.trim(),
          distrito: d.distrito || '',
          provincia: d.provincia || '',
          departamento: d.departamento || '',
          estado: d.estado || '',
          condicion: d.condicion || ''
        });
      }
    }
  }catch(e){ console.log('Decolecta error:', e.message); }

  /* METHOD 2: apis.net.pe fallback */
  try{
    var url2 = isDNI
      ? 'https://api.apis.net.pe/v2/reniec/dni?numero=' + num
      : 'https://api.apis.net.pe/v2/sunat/ruc?numero=' + num;
    var r2 = await fetch(url2, {headers:{'Accept':'application/json','User-Agent':'Mozilla/5.0'},signal:AbortSignal.timeout(6000)});
    if(r2.ok){
      var d2 = await r2.json();
      var n2 = d2.razonSocial||d2.nombre||d2.nombreCompleto||'';
      if(n2) return res.json({tipo:isDNI?'DNI':'RUC',numero:num,nombre:n2.trim(),direccion:d2.direccion||'',distrito:d2.distrito||'',provincia:d2.provincia||'',departamento:d2.departamento||'',estado:d2.estado||'',condicion:d2.condicion||''});
    }
  }catch(e){}

  res.status(404).json({error:'No se encontraron datos. Verifica el numero ingresado.'});
});

app.post('/api/claude',async function(req,res){
  var k=process.env.ANTHROPIC_API_KEY;
  if(!k) return res.status(500).json({error:'Falta configurar ANTHROPIC_API_KEY en Railway. Ve a tu proyecto Railway > Variables > agrega ANTHROPIC_API_KEY con tu key de Anthropic.'});
  try{var r=await fetch('https://api.anthropic.com/v1/messages',{method:'POST',headers:{'Content-Type':'application/json','x-api-key':k,'anthropic-version':'2023-06-01','anthropic-beta':'pdfs-2024-09-25'},body:JSON.stringify(req.body)});var d=await r.json();res.status(r.status).json(d);}
  catch(e){res.status(502).json({error:e.message});}
});

app.post('/api/gemini',async function(req,res){
  var k=process.env.GEMINI_API_KEY;
  if(!k)return res.status(500).json({error:'Falta GEMINI_API_KEY en Railway. Ve a Variables y agrega GEMINI_API_KEY con tu key de aistudio.google.com/apikey'});
  try{
    var parts=[{text:req.body.prompt}];
    if(req.body.imageBase64)parts.push({inline_data:{mime_type:req.body.mimeType||'application/pdf',data:req.body.imageBase64}});
    var body={contents:[{parts:parts}],generationConfig:{temperature:0.1,maxOutputTokens:4000}};
    var r=await fetch('https://generativelanguage.googleapis.com/v1beta/models/gemini-2.5-flash:generateContent?key='+k,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)});
    var d=await r.json();
    res.status(r.status).json(d);
  }catch(e){res.status(502).json({error:e.message});}
});

